<?php
require_once 'config.php';
$pageTitle = 'View Entries';
$search = trim((string)($_GET['search'] ?? ''));
$page = max(1, (int)($_GET['page'] ?? 1));
$perPage = 8;
$like = '%' . $search . '%';
$countStmt = $conn->prepare('SELECT COUNT(*) AS total FROM entries WHERE name LIKE ? OR email LIKE ? OR phone LIKE ?');
$countStmt->bind_param('sss', $like, $like, $like); $countStmt->execute();
$totalRows = (int)$countStmt->get_result()->fetch_assoc()['total'];
$totalPages = max(1, (int)ceil($totalRows / $perPage));
$page = min($page, $totalPages); $offset = ($page - 1) * $perPage;
$stmt = $conn->prepare('SELECT id, name, email, phone, created_at FROM entries WHERE name LIKE ? OR email LIKE ? OR phone LIKE ? ORDER BY id DESC LIMIT ? OFFSET ?');
$stmt->bind_param('sssii', $like, $like, $like, $perPage, $offset); $stmt->execute();
$entries = $stmt->get_result();
require 'header.php';
?>
<div class="page-heading mb-4"><div><p class="eyebrow">READ · SEARCH · SORT</p><h1 class="h2 mb-1">All entries</h1><p class="text-secondary mb-0">Browse and manage records stored in MySQL.</p></div><a href="create.php" class="btn btn-primary">+ Add entry</a></div>
<div class="row g-3 mb-4"><div class="col-sm-6 col-xl-4"><div class="stat-card"><span class="stat-label">Matching entries</span><span class="stat-value"><?= $totalRows ?></span><span class="stat-caption">Records found for this search</span></div></div><div class="col-sm-6 col-xl-4"><div class="stat-card"><span class="stat-label">Current page</span><span class="stat-value"><?= $page ?> <small>/ <?= $totalPages ?></small></span><span class="stat-caption">Showing up to <?= $perPage ?> records per page</span></div></div></div>
<div class="card app-card"><div class="card-body p-3 p-lg-4">
  <form method="get" class="row g-2 align-items-center mb-3" role="search"><div class="col-md"><label class="visually-hidden" for="search">Search entries</label><input class="form-control" id="search" type="search" name="search" value="<?= e($search) ?>" placeholder="Search by name, email, or phone..."></div><div class="col-auto"><button class="btn btn-dark" type="submit">Search</button></div><?php if ($search !== ''): ?><div class="col-auto"><a class="btn btn-outline-secondary" href="view.php">Clear</a></div><?php endif; ?></form>
  <div class="table-responsive"><table class="table table-hover align-middle mb-0" id="entriesTable"><thead class="table-light"><tr><th scope="col">ID</th><th scope="col" class="sortable" onclick="sortTable(1)" role="button">Name <span class="sort-indicator">↕</span></th><th scope="col" class="sortable" onclick="sortTable(2)" role="button">Email <span class="sort-indicator">↕</span></th><th scope="col" class="sortable" onclick="sortTable(3)" role="button">Phone <span class="sort-indicator">↕</span></th><th scope="col" class="sortable" onclick="sortTable(4)" role="button">Created <span class="sort-indicator">↕</span></th><th scope="col" class="text-end">Actions</th></tr></thead><tbody>
  <?php if ($entries->num_rows): while ($row = $entries->fetch_assoc()): ?><tr><td class="text-secondary">#<?= (int)$row['id'] ?></td><td class="fw-semibold"><?= e($row['name']) ?></td><td><a class="email-link" href="mailto:<?= e($row['email']) ?>"><?= e($row['email']) ?></a></td><td><?= e($row['phone']) ?></td><td class="text-secondary small" data-sort-value="<?= e(strtotime($row['created_at'])) ?>"><?= e(date('Y-m-d H:i', strtotime($row['created_at']))) ?></td><td><div class="d-flex justify-content-end gap-2"><a class="btn btn-sm btn-outline-primary" href="update.php?id=<?= (int)$row['id'] ?>">Edit</a><button type="button" class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteModal" data-entry-id="<?= (int)$row['id'] ?>" data-entry-name="<?= e($row['name']) ?>">Delete</button></div></td></tr><?php endwhile; else: ?><tr><td colspan="6" class="text-center py-5"><div class="empty-state-title">No entries found</div><p class="text-secondary mb-3">Try another search or create a new entry.</p><a href="create.php" class="btn btn-primary btn-sm">Add entry</a></td></tr><?php endif; ?>
  </tbody></table></div>
  <?php if ($totalPages > 1): ?><nav class="mt-4" aria-label="Entry pages"><ul class="pagination justify-content-end mb-0"><?php $prev = max(1, $page-1); $next = min($totalPages, $page+1); ?><li class="page-item <?= $page===1?'disabled':'' ?>"><a class="page-link" href="?search=<?= urlencode($search) ?>&page=<?= $prev ?>">Previous</a></li><?php for($p=max(1,$page-2);$p<=min($totalPages,$page+2);$p++): ?><li class="page-item <?= $p===$page?'active':'' ?>"><a class="page-link" href="?search=<?= urlencode($search) ?>&page=<?= $p ?>"><?= $p ?></a></li><?php endfor; ?><li class="page-item <?= $page===$totalPages?'disabled':'' ?>"><a class="page-link" href="?search=<?= urlencode($search) ?>&page=<?= $next ?>">Next</a></li></ul></nav><?php endif; ?>
</div></div>
<div class="text-secondary small mt-3">Tip: click the Name, Email, Phone, or Created headings to sort the visible rows.</div>
